// Router, menu và các inspector dataset cho các trang Pitch v10; nội dung từng trang nằm trong current-platform.js.
const chapters=[['overview','Ý tưởng & DENSO'],['product','Workflow platform'],['sources','Dữ liệu & V2D'],['learning','Dữ liệu → training'],['engine','DreamDojo · Input/Output'],['architecture','Data flywheel'],['validation','PoC Ψ₀ + SIMPLE'],['business','Chi phí & hiệu quả'],['roadmap','Mốc triển khai'],['outcomes','Mở rộng & pilot'],['team','Đội thực hiện'],['research','Paper & toolkit']];
const main=document.querySelector('main');let viewController=new AbortController();

const mobileViewport=matchMedia('(max-width:760px)');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ext=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener">${label} ↗</a>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function media(id){const m=MEDIA[id];return `<figure class="media-card" data-media="${id}"><div class="media-frame">${m.type==='image'?`<img src="${esc(m.url)}" alt="${esc(m.title)}" loading="lazy">`:`<video id="${id}-video" playsinline muted preload="none" ${m.poster?`poster="${esc(m.poster)}"`:''} aria-label="${esc(m.title)}"></video><div class="media-overlay${m.poster?' has-poster':''}">${m.poster?'':`<strong>${esc(m.title)}</strong>`}<button class="media-load" data-load-media="${id}">▶ Xem video</button><span class="media-hint">${m.playbackUrl?'Clip tham khảo · 18,8 giây':'Video từ nguồn tác giả · Tải khi bấm phát'}</span></div>`}</div><figcaption><span class="evidence-label">${m.kind}</span><h3>${m.title}</h3><p>${m.caption}</p><div class="media-credit">${ext(m.source,'Nguồn tác giả')} ${ext(m.url,'Asset gốc')}${m.license?` ${ext(m.license.url,m.license.label)}`:''}</div><p class="media-status" role="status">${m.type==='image'?'':m.playbackUrl?'Clip lưu cùng website để xem nhanh; nguồn gốc được ghi bên trên.':'Bấm Xem video để tải từ nguồn tác giả.'}</p></figcaption></figure>`;}

function closeMenu(){document.querySelector('#sidebar').classList.remove('open');document.querySelector('#veil').hidden=true;document.querySelector('#menu').setAttribute('aria-expanded','false');document.querySelector('#sidebar').inert=mobileViewport.matches;}
mobileViewport.addEventListener('change',closeMenu);
document.querySelector('#menu').addEventListener('click',()=>{const o=!document.querySelector('#sidebar').classList.contains('open');document.querySelector('#sidebar').classList.toggle('open',o);document.querySelector('#sidebar').inert=!o;document.querySelector('#veil').hidden=!o;document.querySelector('#menu').setAttribute('aria-expanded',String(o));});
document.querySelector('#veil').addEventListener('click',closeMenu);
document.querySelector('#navigation').addEventListener('click',e=>{if(e.target.closest('a'))closeMenu();});
document.querySelector('#print').addEventListener('click',()=>window.print());
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const o=document.querySelector('#sidebar').classList.contains('open');closeMenu();if(o)document.querySelector('#menu').focus();}});
function navigate(){
 viewController.abort();viewController=new AbortController();
 if(location.hash==='#main'){main.focus();return;}
 let hash;try{hash=decodeURIComponent(location.hash.slice(1)||'overview');}catch{hash='overview';}
 const aliases={flow:'product',technology:'research','data-core':'architecture','skill-core':'learning',skill:'learning',data:'architecture',ai:'research',production:'roadmap',evaluation:'validation',contracts:'architecture',review:'business',examples:'research'};
 hash=aliases[hash]||hash;const id=chapters.some(([k])=>k===hash)?hash:'overview';
 const navLink=([k,v],i)=>`<a href="#${k}" ${id===k?'class="active" aria-current="page"':''}><span class="nav-number">${String(i+1).padStart(2,'0')}</span>${v}</a>`;
 document.querySelector('#navigation').innerHTML=chapters.slice(0,11).map(navLink).join('')+`<details class="cp-nav-reference" ${id==='research'?'open':''}><summary>Nguồn & minh chứng</summary>${chapters.slice(11).map((r,i)=>navLink(r,i+11)).join('')}</details>`;
 document.querySelector('#crumb').textContent=chapters.find(x=>x[0]===id)[1];
 main.innerHTML=renderCurrentPlatform(id);document.title=`${chapters.find(x=>x[0]===id)[1]} | Humanoid Data Flywheel`;
 initCurrentPlatform(viewController.signal);
 closeMenu();window.scrollTo({top:0,left:0,behavior:'instant'});main.focus({preventScroll:true});
}
window.addEventListener('hashchange',navigate);
function initMedia(root=main,signal=viewController.signal){
 root.querySelectorAll('.media-card').forEach(f=>{
  const id=f.dataset.media,m=MEDIA[id],msg=f.querySelector('.media-status'),v=f.querySelector('video'),img=f.querySelector('img');
  if(img){img.addEventListener('error',()=>{img.hidden=true;msg.textContent='Ảnh không tải được từ máy chủ nguồn; dùng liên kết tác giả/asset để xem.';},{signal});return;}
  const b=f.querySelector('[data-load-media]'),overlay=f.querySelector('.media-overlay'),hint=f.querySelector('.media-hint');let loadTimer;
  const clearTimer=()=>clearTimeout(loadTimer);
  function failed(message){if(signal.aborted)return;clearTimer();overlay.hidden=false;b.disabled=false;b.textContent='↻ Thử tải lại';hint.textContent='Chưa phát được video';msg.textContent=message;}
  function play(){v.play().catch(e=>{if(signal.aborted)return;if(e.name==='NotAllowedError'){clearTimer();overlay.hidden=false;b.disabled=false;b.textContent='▶ Phát video';hint.textContent='Video sẵn sàng · Bấm để phát';msg.textContent='Video đã tải. Bấm Phát video để bắt đầu.';}else if(e.name!=='AbortError'){failed('Không phát được video. Thử tải lại hoặc mở Asset gốc / Nguồn tác giả bên trên.');}});}
  if(id==='g1'||id==='libero'){const end=id==='g1'?20.666667:21.4;v.addEventListener('timeupdate',()=>{if(v.currentTime>=end){v.pause();v.currentTime=0;}},{signal});}
  v.addEventListener('loadeddata',()=>{clearTimer();v.controls=true;msg.textContent='Video tham khảo của tác giả · Dùng nút điều khiển để xem hoặc dừng.';},{signal});
  v.addEventListener('playing',()=>{clearTimer();overlay.hidden=true;b.disabled=false;},{signal});
  v.addEventListener('error',()=>failed('Không tải hoặc phát được video. Thử tải lại hoặc mở Asset gốc / Nguồn tác giả bên trên; phần số liệu vẫn xem được.'),{signal});
  b.addEventListener('click',()=>{
   if(v.readyState>=2&&!v.error){play();return;}
   clearTimer();b.disabled=true;b.textContent='Đang tải video…';hint.textContent=m.playbackUrl?'Đang mở clip tham khảo':'Đang kết nối máy chủ tác giả';msg.textContent=m.playbackUrl?'Đang tải clip GR1…':'Đang tải video từ nguồn tác giả…';
   loadTimer=setTimeout(()=>failed('Video tải lâu hơn dự kiến. Bạn có thể thử lại hoặc mở Asset gốc / Nguồn tác giả bên trên.'),20000);
   if(m.type==='hls'&&!v.canPlayType('application/vnd.apple.mpegurl')){
    if(!window.Hls||!Hls.isSupported()){failed('Trình duyệt chưa hỗ trợ video này. Mở Nguồn tác giả bên trên để xem.');return;}
    if(v._hls)v._hls.destroy();const h=new Hls({maxBufferLength:10});v._hls=h;
    h.loadSource(m.url);h.attachMedia(v);h.on(Hls.Events.MANIFEST_PARSED,play);
    h.on(Hls.Events.ERROR,(_e,d)=>{if(d.fatal){failed('Không tải được video từ nguồn. Thử lại hoặc mở Nguồn tác giả bên trên.');h.destroy();v._hls=null;}});
    signal.addEventListener('abort',()=>h.destroy(),{once:true});
   }else{const url=id==='g1'&&document.querySelector('#robot-camera')?m.url.replace('cam_left_high',document.querySelector('#robot-camera').value):(m.playbackUrl||m.url);v.src=url+(id==='g1'?'#t=0,20.666667':id==='libero'?'#t=0,21.4':'');v.load();play();}
  },{signal});signal.addEventListener('abort',()=>{clearTimer();v.pause();v.removeAttribute('src');v.load();},{once:true});
 });
}
const sampleCache={};
function getSample(name){return sampleCache[name]||(sampleCache[name]=fetch('data/'+name+'.json?v=skill-learning-10').then(r=>{if(!r.ok)throw Error('sample unavailable');return r.json();}).catch(e=>{delete sampleCache[name];throw e;}));}
async function initSamples(signal){
 await Promise.allSettled([
 (document.querySelector('#robot-inspector')?getSample('g1-episode-0'):Promise.resolve(null)).then(d=>{if(!d||signal.aborted)return;const root=document.querySelector('#robot-inspector');
 root.innerHTML=`<h2>observation.state và action</h2><label for="robot-joint">Chọn khớp</label><select id="robot-joint">${d.joints.map((x,i)=>`<option value="${i}">${esc(x)}</option>`).join('')}</select><label for="robot-frame">Frame trong episode 0</label><input id="robot-frame" type="range" min="0" max="619" step="1" value="0"><output id="robot-frame-label"></output><p class="small">Căn theo timestamp/fps; chưa xác minh đồng bộ frame chính xác giữa Rows API và video revision này.</p><div id="robot-values" class="numeric-values"></div><div id="robot-chart" class="chart"></div><label for="robot-camera">Camera video</label><select id="robot-camera"><option value="cam_left_high">Camera trái phía trên</option><option value="cam_right_high">Camera phải phía trên</option><option value="cam_left_wrist">Camera cổ tay trái</option><option value="cam_right_wrist">Camera cổ tay phải</option></select><p class="small">State và action target khác nhau không tự là lỗi. Collector/controller timing và đơn vị chưa xác minh; đồ thị không đánh giá success.</p><details><summary>Xem đủ 28 values ở frame đang chọn</summary><div id="robot-vector"></div></details>`;
 const j=root.querySelector('#robot-joint'),fr=root.querySelector('#robot-frame'),cam=root.querySelector('#robot-camera'),video=document.querySelector('#g1-video');
 function update(seek=false){const r=d.rows[Number(fr.value)],k=Number(j.value);root.querySelector('#robot-frame-label').textContent=`Frame ${r.frame} / 619 · t = ${r.t.toFixed(3)} s`;
 root.querySelector('#robot-values').innerHTML=`<div><span>observation.state</span><strong>${r.state[k].toFixed(5)}</strong></div><div><span>action · target của dataset</span><strong>${r.action[k].toFixed(5)}</strong></div>`;
 const all=d.rows.flatMap(x=>[x.state[k],x.action[k]]),min=Math.min(...all),max=Math.max(...all),span=max-min||1;
 const px=i=>35+i/619*505,py=v=>150-(v-min)/span*115;
 const path=key=>d.rows.map((r,i)=>`${i?'L':'M'}${px(i).toFixed(2)},${py(r[key][k]).toFixed(2)}`).join(' ');
 root.querySelector('#robot-chart').innerHTML=`<svg viewBox="0 0 570 190" role="img" aria-label="Đồ thị observation.state và action cho ${esc(d.joints[k])} trong 620 frames"><text x="5" y="24" font-size="11" fill="#59687b">${max.toFixed(3)}</text><text x="5" y="163" font-size="11" fill="#59687b">${min.toFixed(3)}</text><path d="M35 35V150H540" fill="none" stroke="#cdd7e2"/><path d="${path('state')}" fill="none" stroke="#285ea6" stroke-width="2"/><path d="${path('action')}" fill="none" stroke="#bd2235" stroke-width="2"/><path d="M${px(r.frame)} 35V150" stroke="#a16c21" stroke-dasharray="4 4"/><text x="35" y="180" font-size="11">0s</text><text x="500" y="180" font-size="11">20.63s</text></svg><div class="chart-key"><span>● observation.state</span><span>● action · target của dataset</span></div>`;
 root.querySelector('#robot-vector').innerHTML=table(['Khớp','State','Action'],d.joints.map((n,i)=>[esc(n),r.state[i].toFixed(5),r.action[i].toFixed(5)]));
 if(seek&&video.readyState>=1)video.currentTime=d.videoStart+r.t;
 }
 fr.addEventListener('input',()=>update(true),{signal});j.addEventListener('change',()=>update(),{signal});
 video.addEventListener('timeupdate',()=>{if(video.currentTime>=d.videoEnd){video.pause();video.currentTime=d.rows[619].t;}
 const index=Math.min(619,Math.max(0,Math.round((video.currentTime-d.videoStart)*d.fps)));if(Number(fr.value)!==index){fr.value=String(index);update();}},{signal});
 cam.addEventListener('change',()=>{const figure=document.querySelector('[data-media="g1"]');figure.querySelector('figcaption>p').textContent=cam.selectedOptions[0].textContent+'; '+MEDIA.g1.caption.split('; ').slice(1).join('; ');const t=d.rows[Number(fr.value)].t;video.pause();video.src=HF_G1+'/resolve/'+G1_REV+'/videos/observation.images.'+cam.value+'/chunk-000/file-000.mp4#t='+t+','+d.videoEnd;figure.querySelector('.media-credit a:last-child').href=video.src.split('#')[0];video.load();figure.querySelector('.media-overlay').hidden=true;video.addEventListener('loadedmetadata',()=>{video.currentTime=t;},{once:true,signal});video.play().catch(()=>{});},{signal});update();
 }).catch(()=>{if(!signal.aborted&&document.querySelector('#robot-inspector'))document.querySelector('#robot-inspector').innerHTML='<h2>Không tải được preview local</h2><p>Mở numerical JSON trong phần nguồn hoặc kiểm lại server.</p>';}),
 (document.querySelector('#human-inspector')?getSample('humanego-hands'):Promise.resolve(null)).then(d=>{if(!d||signal.aborted)return;const root=document.querySelector('#human-inspector');
 root.innerHTML=`<h2>Tracking tay và validity</h2><label for="human-row">Chọn tracking row</label><input id="human-row" type="range" min="0" max="1001" step="1" value="0"><output id="human-row-label"></output><div id="human-values"></div><p class="small">Wrist translation trong device frame của recording. Human geometry, không phải robot action. Tracking preview không điều khiển timestamp video.</p><p class="small">CSV: microseconds; camera first_ts: nanoseconds. Preprocessing/crop cần kiểm trước training alignment.</p>`;
 const s=root.querySelector('#human-row');function show(){const r=d.rows[Number(s.value)];root.querySelector('#human-row-label').textContent=`Row ${s.value} / 1001 · timestamp ${r.t_us} µs`;root.querySelector('#human-values').innerHTML=['left','right'].map(h=>{const x=r[h];return `<div class="tracking-row ${x.valid?'valid':'missing'}"><strong>${h==='left'?'Tay trái':'Tay phải'} · ${x.valid?'có tracking':'thiếu tracking'}</strong><span>Confidence: ${x.confidence.toFixed(6)}</span><span>Raw wrist: [${x.rawWrist.map(v=>v.toFixed(5)).join(', ')}]</span><span>Normalized: ${x.valid?'['+x.wrist.map(v=>v.toFixed(5)).join(', ')+']':'null · mask = false'}</span></div>`;}).join('');}s.addEventListener('input',show,{signal});show();
 }).catch(()=>{if(!signal.aborted&&document.querySelector('#human-inspector'))document.querySelector('#human-inspector').innerHTML='<h2>Không tải được tracking preview</h2><p>Numerical JSON và nguồn được liên kết trong hồ sơ.</p>';})
 ]);
}
async function initGR1(signal){try{const d=await getSample('gr1-preview');if(signal.aborted)return;const el=main.querySelector('#gr1-inspector');if(!el)return;el.innerHTML=`<p class="small"><strong>Instruction đã tra task index:</strong> ${esc(d.taskPreview.task)}</p><p class="small">Inspector giữ 6 rows đầu, chọn độc lập với player; không tự đồng bộ số với frame video đang phát.</p><label for="gr1-frame">Frame trong mẫu GR1</label><select id="gr1-frame">${d.rows.map((r,i)=>`<option value="${i}">Row ${i} · ${r.timestamp.toFixed(2)}s</option>`).join('')}</select><label for="gr1-dimension">Dimension state/action</label><select id="gr1-dimension">${Array.from({length:29},(_,i)=>`<option value="${i}">Dimension ${i}</option>`).join('')}</select><div id="gr1-values"></div><details><summary>Đủ 29 values và raw row</summary><pre id="gr1-raw"></pre></details>`;const f=el.querySelector('#gr1-frame'),j=el.querySelector('#gr1-dimension');function show(){const r=d.rows[Number(f.value)],k=Number(j.value);el.querySelector('#gr1-values').innerHTML=`<p class="small">episode=${r.episode_index} · task_index=${r.task_index} · index=${r.index} · t=${r.timestamp.toFixed(3)}s</p><div class="numeric-values"><div><span>observation.state[${k}]</span><strong>${r['observation.state'][k].toFixed(5)}</strong></div><div><span>action[${k}] · dataset target</span><strong>${r.action[k].toFixed(5)}</strong></div></div><p class="small">Dimension index không tự là joint name/unit; metadata mẫu không ghi tên từng chiều. next.reward=${r['next.reward']}, next.done=${r['next.done']}; 6 rows đầu không đủ kết luận episode success.</p>`;el.querySelector('#gr1-raw').textContent=JSON.stringify(r,null,2);}f.addEventListener('change',show,{signal});j.addEventListener('change',show,{signal});show();}catch(e){if(!signal.aborted&&main.querySelector('#gr1-inspector'))main.querySelector('#gr1-inspector').textContent='Không đọc được preview GR1 local. Dùng JSON và source link bên dưới.';}}
async function initLibero(signal){try{const d=await getSample('libero-preview');if(signal.aborted)return;const el=main.querySelector('#libero-inspector');if(!el)return;el.innerHTML=`<p><strong>Instruction của task 0:</strong> ${esc(d.taskPreview.__index_level_0__)}</p><p class="small">Episode 0: ${d.episodePreview.length} frames, 10fps; video segment 0–21,4s. Preview số chỉ 6 frames đầu, không tự chạy theo player.</p><label for="libero-frame">Frame trong preview</label><select id="libero-frame">${d.rows.map((r,i)=>`<option value="${i}">Frame ${r.frame_index} · ${r.timestamp.toFixed(1)}s</option>`).join('')}</select><div id="libero-values"></div>`;const s=el.querySelector('select');function show(){const r=d.rows[Number(s.value)];el.querySelector('#libero-values').innerHTML=`<p class="small">episode_index=${r.episode_index} · task_index=${r.task_index} · timestamp=${r.timestamp.toFixed(3)}s · index=${r.index}</p>`+table(['Dimension index','observation.state (8)','action (7)'],r['observation.state'].map((v,i)=>[i,v.toFixed(7),r.action[i]===undefined?'Không có dimension này':r.action[i].toFixed(7)]))+`<details><summary>Xem raw row đã lấy từ public dataset</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details>`;}s.addEventListener('change',show,{signal});show();}catch(e){if(!signal.aborted&&main.querySelector('#libero-inspector'))main.querySelector('#libero-inspector').textContent='Không đọc được preview local. Mở file JSON hoặc dataset ở link nguồn.';}}
navigate();
